    terms = []
    for i, coeff in enumerate(coeffs):
        if coeff == 0:
            continue
        term = ""
        if coeff < 0:
            term += "-"
        elif coeff > 0 and i != 0:
            term += "+"
        if abs(coeff) != 1 or i == n:
            term += str(abs(coeff))
        if i != n:
            term += "x^" + str(n - i)
        terms.append(term)
    return "".join(terms)

